#ifndef CRUMP_BIT_EFFECT_H_
#define CRUMP_BIT_EFFECT_H_


/*
 * CrumpBit loop geometry (S074_CRUMPBIT_EFFECT.md §3.4; elastic since S091
 * P2 §5.1; retuned in S091 P3 N1).
 *
 * CRUMPBIT_DELAY_CURVE_MAX: the longest delay, 126,654 samples (2.871 s at
 * 44,108 Hz; S091 P6: row 127 of the `dly` delay-time curve, t_max of
 * crumpBit_delayCurve(); it was crumpBit_rateTable[127]): the arena less one
 * 32 B granule and the 2-sample interpolation guard. S091 P3 grew the
 * runtime by 16 B; whether `.dtcmz` then crosses a 32 B boundary (moving
 * `_sfxbuf` up one granule, 126,688 -> 126,656 B) depends on how LTO packs
 * the DTCM statics (the measured S091 P3 build absorbed it in padding). The
 * curve top is set to the smaller arena, so `rte` 127 fits either way (N1,
 * user); a 126,688 B arena leaves 32 B unused.
 * CRUMPBIT_LOOP_MAX_BYTES: the longest loop CrumpBit seats, the curve top plus
 * the guard (126,656 B, a multiple of 32). A
 * larger share is not used beyond it; a smaller share (voice units claimed
 * from the top) shortens the loop, and the Rate row and the DSP target are
 * clamped to what it holds (the loop is elastic).
 * CRUMPBIT_LOOP_MIN_SHARE_BYTES: the share left at this arena size with all
 * twelve voice units claimed (73,664 B): declared as buffer_min_bytes.
 * CrumpBit still works below it (down to CRUMPBIT_LOOP_MIN samples); the
 * field is declarative.
 * Accessors: CrumpBitEffect.c, EffectsManager.c (registry row).
 * Affiliates: FxBuffer.h FXBUF_VOICE_UNIT_*, tools/plots/gen_crumpbit_tables.py
 * (RATE_MAX), tools/diagnostic_tools/link_budget.py (FXBUF size).
 */
#define CRUMPBIT_DELAY_CURVE_MAX       126654.0f
#define CRUMPBIT_LOOP_MAX_BYTES        126656u
#define CRUMPBIT_LOOP_MIN_SHARE_BYTES                                   \
    (CRUMPBIT_LOOP_MAX_BYTES -                                          \
     FXBUF_VOICE_UNIT_COUNT * FXBUF_VOICE_UNIT_BYTES)

/*
 * Single-line tape state: `dly` and `cmb` (engine A; S091 P3 §2.2).
 *
 * What: the S091 P2 delay state, now one member of the sub-type union.
 * - length, write_pos, valid: the COMMON PREFIX of every single-line
 *   sub-type (`dly`, `cmb`, `pit`): loop length in bytes (0 = unseated), the
 *   next index to write, and the samples written since the loop was last
 *   treated as empty (reads further back are muted). It sits at offset 0 in
 *   each of them, so a switch between them keeps the recording (§2.4);
 * - delay: the gliding delay in samples (tape glide; never above
 *   length - 2);
 * - dc_x, dc_y: the in-loop DC blocker memories (feedback can exceed 1);
 * - tone_s: the one-pole state of the `ton` tilt on the feedback return.
 * Size: 28 B. Accessors: CrumpBitEffect.c only.
 */
typedef struct {
    uint32_t length;
    uint32_t write_pos;
    uint32_t valid;
    float delay;
    float dc_x;
    float dc_y;
    float tone_s;
} CrumpBitTapState;

/*
 * Pitch-shifter state: `pit` (engine B; S091 P3 §3.2).
 *
 * What: the common prefix (length, write_pos, valid, as CrumpBitTapState),
 * then phase: the rotating-head phase, an unsigned 0.32 fraction of a turn
 * that wraps by integer overflow (head A trails the write head by
 * 2 + W*phase, head B by 2 + W*(phase + 1/2), the half turn being one
 * 32-bit add), and the same feedback-return memories as the tape (dc_x,
 * dc_y, tone_s).
 * - window (S091 P5 follow-up, user): the head window W in samples as it
 *   glides towards the `rte` target (CRUMPBIT_PITCH_WIN_GLIDE, ~20 ms), so
 *   a `win` change slides the heads instead of jumping them. Set to the
 *   target on the first block (`primed`), clamped to the loop every block.
 * Size: 32 B (28 B before; inside the 44 B union, no runtime growth).
 * Accessors: CrumpBitEffect.c only.
 */
typedef struct {
    uint32_t length;
    uint32_t write_pos;
    uint32_t valid;
    uint32_t phase;
    float dc_x;
    float dc_y;
    float tone_s;
    float window;
} CrumpBitPitchState;

/*
 * Granular state: `grn` (engine B'; S091 P3, reworked in S091 P4,
 * S091_P4_GRN_TWEAKS.md Part A).
 *
 * What: the share is split into a record line (first half) and a delay line
 * (second half) of `length` samples each (N), written at the same
 * write_pos. Two grain voices, A and B, read the record line; each is
 * triggered by Density, independently of its Length.
 * - pos_a, pos_b: the voices' read positions in the record line, 16.16
 *   fixed point (integer part = sample index; drop-sample reads, user G6);
 * - countdown: frames from the next block start to the next Density
 *   trigger. 32-bit: a random interval reaches 2 N (126,656 frames);
 * - fit_key (S091 P5 G6, in the 4 B the delay line's DC blocker `dc_x`
 *   held until G4 removed it): the tempo and line length the cached
 *   Position fit was worked out for, BPM | N << 16. A line is at least
 *   CRUMPBIT_GRAIN_LINE_MIN long while the engine runs, so the zeroed key
 *   (enter, init, the manager's union clear) never matches and the first
 *   block works the fit out;
 * - tap_d, tap_on, tap_spare (S091 P6, in the 4 B of G4's former `dc_y`,
 *   the S091 P5 `reserved` word, so the state stays 44 B and the runtime
 *   100 B): the delay-line tap's fade (user: one block). tap_d is the
 *   delay D (frames) the tap reads now; tap_on is its gain at the block
 *   start, 1 or 0. When the `rte` delay time moves away from tap_d, the tap
 *   fades to 0 over one block, tap_d jumps to the new D while silent, and
 *   the tap fades back in over the next block (crumpBit_runGrain()). The
 *   zeroed union (enter, init) and a reseat (crumpBit_seatActive()) leave
 *   tap_on 0, so the tap starts silent at the current D. tap_spare is free;
 * - inc_a, inc_b: the voices' pitch steps, signed Q3.12 (ratio x 4096;
 *   negative = reversed); pos += inc x 16 per frame;
 * - age_a, age_b: frames since the voice started (saturating at its end);
 * - end_a, end_b: the frames the voice sounds, L + 128, latched at its
 *   start (0 = idle): a fade-in over the first 128 frames, flat, and a
 *   fade-out over the 128 frames after its Length L, so back-to-back
 *   grains crossfade with complementary fades (the copy setting is
 *   seamless, plan A1.9). A steal sets end = age + 128 + pad (the
 *   fade-out starts at once, from a held 1 for `pad` frames). S091 P5 G3:
 *   every end lands on a block boundary (a grain's span is rounded down, a
 *   steal's pad rounds its end up), so a voice never runs past its end
 *   inside a block. A voice is free once age >= end;
 * - write_pos, length (N), valid: 16-bit (a line is at most 63,328);
 * - anchor: the record head position when freeze began (positions are
 *   measured from it while frozen, plan A3.3); CRUMPBIT_GRAIN_NO_ANCHOR
 *   (0xFFFF, above any line) while not frozen;
 * - pan_a, pan_b: each voice's pan byte (0 left .. 127 centre .. 254
 *   right), drawn at its start from `wid` (plan A1.4);
 * - pending: a stolen voice's deferred trigger (plan A3.1): 0 = none, else
 *   1 + the frames from the next block start to the trigger;
 * - fit (S091 P5 G6, the former alignment byte): the cached Position fit,
 *   how many rhythmic stops (0..16, shortest first) fit one line at the
 *   tempo in fit_key (crumpBit_grainStopFit()).
 * The delay-line tap reads exactly tap_d behind the write head (whole
 * frames, no glide); only its gain moves (the fade above).
 * Size: 44 B (the union's largest member; S091 P4: +12 B over the S091 P3
 * 32 B, inside the user's +32 B approval). Accessors: CrumpBitEffect.c.
 */
typedef struct {
    uint32_t pos_a;
    uint32_t pos_b;
    uint32_t countdown;
    uint32_t fit_key;
    uint16_t tap_d;
    uint8_t tap_on;
    uint8_t tap_spare;
    int16_t inc_a;
    int16_t inc_b;
    uint16_t age_a;
    uint16_t age_b;
    uint16_t end_a;
    uint16_t end_b;
    uint16_t write_pos;
    uint16_t length;
    uint16_t valid;
    uint16_t anchor;
    uint8_t pan_a;
    uint8_t pan_b;
    uint8_t pending;
    uint8_t fit;
} CrumpBitGrainState;

/* `anchor` while not frozen: above any line length (lines <= 63,328). */
#define CRUMPBIT_GRAIN_NO_ANCHOR   0xFFFFu

/*
 * Reverb state: `rvb` (engine C; S091 P3 §3.4).
 *
 * What: the share is used as 32-bit words, one per sample, each holding the
 * four FDN lines' 8-bit values (one lane per line). write_pos and length are
 * in words; valid counts words written since the loop was treated as empty
 * (the wet path and the line feedback open per block once it covers the
 * longest line); damp[4] are the per-line one-pole states of the `ton`
 * damping.
 * Size: 28 B. Accessors: CrumpBitEffect.c only.
 */
typedef struct {
    uint32_t write_pos;
    uint32_t length;
    uint32_t valid;
    float damp[4];
} CrumpBitReverbState;

/*
 * CrumpBit runtime (100 B since S091 P4; 88 B in S091 P3; a member of
 * EffectsManager's DTCM runtime union; user-approved growth up to +32 B over
 * 76 B, 2026-11-04).
 *
 * What: a SHARED part used by every sub-type (stages 1, 3 and 4 and all row
 * bytes), then a UNION of the sub-engines' DSP states (stage 2).
 * Shared part (55 B used, 1 B padding before the union since the S091 P5
 * follow-up's `pit_fine`):
 * - ac_y_*, ac_c_*: stage 1 AC coupling (outputs; previous codes, int16,
 *   seeded 128 by init);
 * - svf_*: the output filter's two TPT integrators per channel (stage 4),
 *   the same filter in every sub-type since S094 P2 AS-13 (the S091 P5 F1
 *   one-pole of `grn` and `rvb` is gone), so a switch keeps them as they
 *   are;
 * - row bytes, written by write_param() whatever the sub-type: their
 *   meaning changes per sub-type, their storage does not (plan §2.2);
 * - subtype: the resolved `sub` row; active_subtype: the engine that ran
 *   last block. A difference triggers crumpBit_enter() (plan §2.4);
 * - *_prev: the raw rows the previous block ramped to (ramp origins: the
 *   mix stage and the output filter's type and resonance). S091 P5 S1 removed
 *   feedback_prev and pan_prev: `fbk` and `dpn` take their target at the
 *   block start, so they have no origin to keep;
 * - primed: 0 until the first block of a tape sub-type starts its glide on
 *   the target (S091 P5: also `pit`'s window glide);
 * - drv_reserved: the deferred output-filter drive row's byte (plan OQ6);
 * - pit_fine: row 23 (S091 P5 follow-up), `pit`'s fine pitch, in one of the
 *   two padding bytes S1 freed (the runtime stays 100 B);
 * - filter_bal: row 22 (S091 P4), the output filter's stereo balance; it
 *   took the alignment byte. Since S091 P5 (S1) freed two bytes, the used
 *   shared bytes are 54 and 2 B of padding precede the union (56 B in all).
 * Union (44 B, `grn` the largest): one of the five states above.
 * Why here: EffectsManager zeroes the union and calls init() when the type
 * becomes active. Accessors: CrumpBitEffect.c only; no other module may keep
 * a pointer. Affiliates: effects_runtime_t, the size guard in
 * CrumpBitEffect.c, STORAGE_SRAM_MANIFEST.md.
 */
typedef struct {
    float ac_y_l;              /* stage 1 */
    float ac_y_r;              /* stage 1 */
    float svf_l1;              /* stage 4: TPT band integrator, left */
    float svf_l2;              /* stage 4: TPT low integrator, left */
    float svf_r1;              /* stage 4: TPT band integrator, right */
    float svf_r2;              /* stage 4: TPT low integrator, right */
    int16_t ac_c_l;            /* stage 1: previous code, left */
    int16_t ac_c_r;            /* stage 1: previous code, right */
    uint8_t bit_off;           /* row 3, shared */
    uint8_t bit_invert;        /* row 4, shared */
    uint8_t mix_raw;           /* row 5, shared: the mix stage */
    uint8_t feedback_raw;      /* row 6, sub-type row */
    uint8_t rate;              /* row 7, sub-type row */
    uint8_t subtype;           /* row 8, shared: resolved sub-type */
    uint8_t sync;              /* row 9, sub-type row */
    uint8_t pan_raw;           /* row 10, sub-type row */
    uint8_t tone_raw;          /* row 11, sub-type row */
    uint8_t filter_type;       /* row 12, shared */
    uint8_t filter_freq;       /* row 13, shared */
    uint8_t filter_reso;       /* row 14, shared */
    uint8_t aux_raw;           /* row 15, sub-type row (pitch) */
    uint8_t grain_st2;         /* row 16, grn */
    uint8_t grain_st3;         /* row 17, grn */
    uint8_t grain_spread;      /* row 18, grn */
    uint8_t grain_density;     /* row 19, grn */
    uint8_t grain_length;      /* row 20, grn: Length (S091 P4) */
    uint8_t grain_width;       /* row 21, grn */
    uint8_t active_subtype;    /* the engine that ran last block */
    uint8_t mix_prev;          /* mix stage ramp origin */
    uint8_t filter_type_prev;  /* stage 4 ramp origin */
    uint8_t filter_reso_prev;  /* stage 4 ramp origin */
    uint8_t primed;            /* tape glide primed */
    uint8_t drv_reserved;      /* deferred drive row (plan OQ6) */
    uint8_t filter_bal;        /* row 22, shared: filter balance (P4) */
    uint8_t pit_fine;          /* row 23, pit: fine pitch (P5 follow-up) */
    union {
        CrumpBitTapState tap;      /* dly, cmb */
        CrumpBitPitchState pit;    /* pit */
        CrumpBitGrainState grn;    /* grn */
        CrumpBitReverbState rvb;   /* rvb */
    } u;
} CrumpBitRuntime;

/* DSP operations for the registry row (init, export, write, process, share). */
extern const effect_type_ops_t crumpBit_ops;

/*
 * `dly` delay time of one `rte` row at one tempo (S091 P6, user).
 *
 * What: the row's delay in samples on `dly`'s 128-row curve: rows 0..3 from
 * the 2-sample minimum up towards /64; rows 4..123 the tempo-synced core,
 * StepScale's stops /64 .. /2 exact (crumpBit_delayTicks,
 * crumpBit_delayStopCc); rows 124..127 from /2 up to
 * CRUMPBIT_DELAY_CURVE_MAX (row 127). Every row is distinct (each step
 * changes the delay and the label) and clamped to CRUMPBIT_DELAY_CURVE_MAX;
 * the share clamp is the caller's. It replaced the S091 P2 free-running
 * Rate curve and the Sync snap to StepScale (crumpBit_rateSamples(),
 * crumpBit_syncDivision()), whose two curves gave dead knob travel and
 * jumps of two positions.
 * Why shared: the DSP target, the share clamp (crumpBit_subtypeRateLimit())
 * and the Effect-page label read one curve.
 * Inputs: rate 0..127 (above reads 127), bpm (0 = 1). Output: samples.
 * Accessors: crumpBit_runDelay(), crumpBit_uiFormatValue3(), host law CB1.
 */
float crumpBit_delaySamples(uint8_t rate, uint16_t bpm);

/*
 * Longest delay a share holds (S091 P2).
 *
 * What: min(share bytes, CRUMPBIT_LOOP_MAX_BYTES) - 2 samples (the
 * interpolation guard), as a float; 0 when there is no share or it is
 * smaller than the smallest usable loop. It is exactly the clamp
 * crumpBit_process() applies to its target for the same share.
 * Input: share (may be NULL). Output: samples.
 * Accessors: crumpBit_subtypeRateLimit(), crumpBit_process() (target
 * clamp).
 */
float crumpBit_shareMaxSamples(const fx_share_t *share);

/*
 * Sub-engine helpers shared with the page (S091 P3).
 *
 * crumpBit_subtypeRateLimit(): the largest `rte` whose length fits the share
 * under one sub-type's law (the `dly` delay-time curve at the current tempo
 * (S091 P6), comb table, pitch window, the `grn`
 * delay-time curve within a half line at the current tempo (S091 P4), the
 * `rvb` word buffer); the effective_max op and the Rate label use it.
 * crumpBit_grainMaxSamples(): the longest `grn` delay or lag, one half line
 * less the guard. crumpBit_combNote(): the MIDI note a `cmb` `rte` plays
 * (112 - rte, clamped at 96), for the note-name label.
 * crumpBit_grainPosLimit() (S091 P4): the largest `dpn` (Position) value in
 * `grn` whose rhythmic lag fits a half line at the current tempo; values at
 * or below 63 (follow, scatter) are never limited (plan A1.8, A3.4). S091
 * P5 A: the page label and host law CB6 use it; the DSP clamps the stop
 * itself with the same fit (crumpBit_grainStopFit()), so `dpn` is no longer
 * BUFFER_DEPENDENT and the manager never clamps it.
 * Inputs: sub-type id, share (may be NULL), or the raw `rte`. Outputs: as
 * named. Accessors: CrumpBitEffect.c, crumpBit_uiFormatValue3().
 */
uint8_t crumpBit_subtypeRateLimit(uint8_t subtype, const fx_share_t *share);
float crumpBit_grainMaxSamples(const fx_share_t *share);
uint8_t crumpBit_combNote(uint8_t rate);
uint8_t crumpBit_grainPosLimit(const fx_share_t *share);

/*
 * `grn` rhythmic stop of a Position or Density value (S091 P4, plan A1.8).
 *
 * What: the knob value -> index into crumpBit_grainStopCc (0 = /64 .. 15 =
 * 1br), or CRUMPBIT_GRAIN_NO_STOP outside the rhythmic half.
 * - Position: 64..127 (positive) -> (v - 64) / 4: four values per stop,
 *   shortest first, so turning up plays later.
 * - Density: 64 is +1 (one trigger per N, not a stop); 65..127 -> 15 -
 *   (v - 65) x 16 / 63: the longest stop (1br) first, shorter periods (more
 *   grains) as the knob turns up.
 * Why shared: the DSP and the page label must name the same division.
 * Inputs: the stored row value. Output: 0..15 or CRUMPBIT_GRAIN_NO_STOP.
 * Accessors: crumpBit_runGrain(), crumpBit_grainPosLimit(),
 * crumpBit_uiFormatValue3().
 */
#define CRUMPBIT_GRAIN_NO_STOP   0xFFu

static inline uint8_t crumpBit_grainPosStop(uint8_t value)
{
    return (value > 63u) ? (uint8_t)((value - 64u) / 4u)
                         : (uint8_t)CRUMPBIT_GRAIN_NO_STOP;
}

static inline uint8_t crumpBit_grainDenStop(uint8_t value)
{
    return (value > 64u)
        ? (uint8_t)(15u - ((uint32_t)(value - 65u) * 16u) / 63u)
        : (uint8_t)CRUMPBIT_GRAIN_NO_STOP;
}

/*
 * Per-sub-type FX lane maps (S091 P3 §2.9).
 *
 * What: the 16-entry lane -> row table for one `sub` value. Nine lanes are
 * shared by every map (0 Morph, 1 bof, 2 biv, 3 mix, 7 vol, 8 pan, 11 typ,
 * 12 frq, 13 res; lane 3 `mix` is never freeable); the seven-lane pool
 * (4, 5, 6, 9, 10, 14, 15) is assigned per sub-type (user L1/L2). The `dly`
 * map is the S091 P2 table, so `.fx` files round-trip unchanged.
 * Input: the `sub` value (anything above the last id reads the last map).
 * Output: a const 16-entry table in flash.
 * Accessors: crumpBit_ops.lane_map (EffectsManager's effects_laneTable());
 * defined in CrumpBitEffect.c beside the ops table (host-tested, CB9).
 */
const uint8_t *crumpBit_laneMap(uint8_t variant);

#endif /* CRUMP_BIT_EFFECT_H_ */

